import {tileKind} from './world.js';
import {CHART_GROUPS} from './navigation.js';
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function chartMarkup(map,game,markers){
 const title=map.floorName||map.chapter[map.place];
 return `<div class="chart-heading"><div><span class="eyebrow">${escape(map.chapter.island)} · ${map.place==='dungeon'?`遗迹 ${map.depth+1} / 4 层`:map.place==='route'?'群岛原野':'港口停靠处'}</span><h3>附近的道路与地点</h3></div><span class="chart-compass" aria-hidden="true">N<svg viewBox="0 0 80 80"><circle cx="40" cy="40" r="31"/><path d="M40 4 47 33 76 40 47 47 40 76 33 47 4 40 33 33Z"/><path d="M40 13V67M13 40H67"/></svg></span></div><div class="chart-layout"><div class="chart-map-column"><div class="local-chart-frame"><canvas id="local-chart" width="840" height="560" role="img" aria-label="${escape(title)}随身地图。白色圆点是你的位置；在下方选择地点可查看步行路线。"></canvas><div class="local-chart-caption"><span>${escape(title)}</span><small>○ 你的位置 · 虚线为步行路线</small></div></div></div><aside class="chart-sidebar"><div class="chart-filters" role="group" aria-label="筛选地图地点"><button data-chart-filter="all" class="active" aria-pressed="true">全部地点</button>${Object.entries(CHART_GROUPS).filter(([key])=>markers.some(m=>m.group===key)).map(([key,g])=>`<button data-chart-filter="${key}" aria-pressed="false">${g.symbol} ${g.name}</button>`).join('')}</div><div class="chart-selected" id="chart-selected" aria-live="polite"><p>选一个想去的地点，看看脚下的路。</p><small>行走途中仍会遇到野生潮灵；方向键或打开菜单可随时停下。</small></div><div class="chart-places" id="chart-places">${markers.map((m,i)=>`<button data-chart-target="${escape(m.id)}" data-chart-group="${m.group}" aria-pressed="false" style="--marker-color:${CHART_GROUPS[m.group].color}"><span class="chart-place-number">${String(i+1).padStart(2,'0')}</span><span><strong>${escape(m.label||CHART_GROUPS[m.group].name)}</strong><small>${m.tracked?'正在追踪 · ':''}${escape(m.status||CHART_GROUPS[m.group].name)}</small></span><b>↗</b></button>`).join('')}</div></aside></div><div class="chart-footer"><p>不会自动拾取、交付、进入出口或发起挑战。到达后按 E / 互动继续。</p><button class="secondary" id="chart-islands">群岛航线</button><button class="text-button" id="chart-close">收起航图 →</button></div>`;
}
export function selectedChartMarkup(marker,path){
 const group=CHART_GROUPS[marker.group],reachable=path!==null;
 return `<div><small style="color:${group.color}">${group.symbol} ${group.name}</small><h3>${escape(marker.label||group.name)}</h3><p>${!reachable?'暂时没有可通行的道路。先寻找附近机关，或换一条来路。':path.length===0?'已经来到附近，收起航图后即可互动。':`步行 ${path.length} 格 · 沿途遭遇可能中断路线`}</p></div><button class="${reachable?'primary':'secondary'}" id="chart-go" ${reachable?'':'disabled'}>${!reachable?'道路尚未连通':path.length?'沿这条路前往 →':'收起航图，准备互动 →'}</button>`;
}
export function drawLocalChart(ctx,map,game,markers,{selected=null,path=null,filter='all',walkable=null}={}){
 const {width,height}=ctx.canvas,pad=26,cell=Math.min((width-pad*2)/map.width,(height-pad*2)/map.height),ox=(width-map.width*cell)/2,oy=(height-map.height*cell)/2;
 const displayWidth=Math.min(ctx.canvas.clientWidth||width,(ctx.canvas.clientHeight||height)*width/height),markerScale=width/displayWidth;
 ctx.clearRect(0,0,width,height);ctx.fillStyle='#0c2029';ctx.fillRect(0,0,width,height);ctx.imageSmoothingEnabled=false;
 const colors={water:map.chapter.palette[3],grass:map.chapter.palette[0],flowers:map.chapter.palette[0],path:'#baa67f',sand:map.region===4?'#b4c4c5':'#b7a184',snow:'#acbec1',stone:'#607678',wood:'#b78b64',wall:'#193941'};
 for(let y=0;y<map.height;y++)for(let x=0;x<map.width;x++){ctx.fillStyle=colors[tileKind(map,x,y)]||'#193941';ctx.fillRect(ox+x*cell,oy+y*cell,cell+.2,cell+.2);if(walkable&&!walkable[y*map.width+x]&&!['water','wall'].includes(tileKind(map,x,y))){ctx.fillStyle='#132c37aa';ctx.fillRect(ox+x*cell,oy+y*cell,cell+.2,cell+.2);}}
 ctx.strokeStyle='#f3e2b719';ctx.lineWidth=1;for(let x=0;x<=map.width;x+=7){ctx.beginPath();ctx.moveTo(ox+x*cell,oy);ctx.lineTo(ox+x*cell,oy+map.height*cell);ctx.stroke();}for(let y=0;y<=map.height;y+=7){ctx.beginPath();ctx.moveTo(ox,oy+y*cell);ctx.lineTo(ox+map.width*cell,oy+y*cell);ctx.stroke();}
 if(path?.length){ctx.beginPath();ctx.moveTo(ox+(game.x+.5)*cell,oy+(game.y+.5)*cell);for(const [x,y] of path)ctx.lineTo(ox+(x+.5)*cell,oy+(y+.5)*cell);ctx.strokeStyle='#142b30';ctx.lineWidth=6;ctx.stroke();ctx.setLineDash([7,5]);ctx.strokeStyle='#ffe1a6';ctx.lineWidth=3;ctx.stroke();ctx.setLineDash([]);}
 for(const [i,m] of markers.entries()){
  if(filter!=='all'&&m.group!==filter&&m.id!==selected)continue;const x=ox+(m.x+.5)*cell,y=oy+(m.y+.5)*cell,active=m.id===selected;
  if(active){ctx.beginPath();ctx.arc(x,y,13*markerScale,0,Math.PI*2);ctx.strokeStyle='#fff0b6';ctx.lineWidth=2;ctx.stroke();}
  ctx.beginPath();ctx.arc(x,y,(active?9:8)*markerScale,0,Math.PI*2);ctx.fillStyle='#112b35';ctx.fill();ctx.strokeStyle=CHART_GROUPS[m.group].color;ctx.lineWidth=active?2:1.5;ctx.stroke();ctx.fillStyle=CHART_GROUPS[m.group].color;ctx.textAlign='center';ctx.textBaseline='middle';ctx.font=`bold ${10*markerScale}px sans-serif`;ctx.fillText(String(i+1),x,y+.5);
 }
 const px=ox+(game.x+.5)*cell,py=oy+(game.y+.5)*cell;ctx.fillStyle='#fff6da';ctx.strokeStyle='#163441';ctx.lineWidth=3;ctx.beginPath();ctx.arc(px,py,5*markerScale,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.strokeStyle='#c6bd8a4d';ctx.lineWidth=1;ctx.strokeRect(ox-.5,oy-.5,map.width*cell+1,map.height*cell+1);
}
